{
  "technical_and_design_decisions": [
    "Use spring-boot-starter-security dependency to provide Basic Auth in spring-xd-dirt, toggled by server.basic.enabled property with default false in application.yml.",
    "Externalize single-user security configuration through servers.yml using Spring Boot security properties (e.g., security.user.name/password).",
    "Extend XD Shell admin config command with --username and --password options, sending credentials via HTTP Basic Auth header to a secured admin server.",
    "Update dependency management to latest Spring Boot 1.1.x RELEASE and provide a snapshot profile to satisfy U4 and U5.",
    "Treat U6 as a spike only: produce design document and user stories, no production REST API implementation in this increment.",
    "Build Docker images via Dockerfiles using Ubuntu base, installing Java 7, and (for sandbox) Redis and RabbitMQ, then copying the existing Full XD Jar.",
    "Configuration properties follow existing Spring Boot YAML conventions (application.yml, servers.yml)."
  ],
  "assumptions": [
    "The existing codebase is Spring XD (including spring-xd-dirt and XD Shell) and uses a Maven build system.",
    "References to 'latest Spring Boot' in the spec correspond to the 1.1.x line mentioned in U1/U2.",
    "Java 7 is the target JVM for Docker images as explicitly stated, regardless of later Spring Framework Java version requirements.",
    "The Full XD Jar is already produced by existing build processes; Docker tasks only wrap it into images.",
    "Effort estimates include local unit testing and developer verification but exclude dedicated QA, CI pipeline changes, and production deployment.",
    "A single developer performs all activities sequentially; estimates are expressed in work-hours, not elapsed calendar days.",
    "U6 is limited to spike activities (assessment, documentation, story creation); full REST API implementation is deferred."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Update to Spring Boot RELEASE dependency",
      "activity_description": "Modify build configuration to pull latest Spring Boot RELEASE (1.1.x) as a dependency across relevant modules (spring-xd-dirt, XD Shell) to inherit OOTB security features (U5).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "Add Spring Boot SNAPSHOT dependency option",
      "activity_description": "Configure build to allow pulling latest Spring Boot SNAPSHOT dependency via a profile or repository setting so snapshot features can be inherited (U4).",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement Basic Auth in spring-xd-dirt",
      "activity_description": "Add spring-boot-starter-security to spring-xd-dirt, control via server.basic.enabled property (default false in application.yml) as per U1, and verify conditional challenge for username/password.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A4",
      "activity_name": "Single-user security configuration via servers.yml",
      "activity_description": "Enable single-user security configurations (e.g., security.user.*) to be provided/overridden through servers.yml file, leveraging Spring Boot security properties (U2).",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A5",
      "activity_name": "XD Shell admin config credentials",
      "activity_description": "Extend XD Shell 'admin config' command with --username and --password options, store them, and use Basic Auth when communicating with a secured admin server (U3).",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A6",
      "activity_name": "REST API archive upload spike",
      "activity_description": "Assess customer requirement, brainstorm and document options for a REST API to upload an archive with custom module definitions, socialize with team, identify phases, and create new stories (U6). No full implementation.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A7",
      "activity_name": "Sandbox Docker image",
      "activity_description": "Create Dockerfile and build a 'sandbox' image based on Ubuntu with Full XD Jar, Java 7.x, Redis, and RabbitMQ for experimentation (U7).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A8",
      "activity_name": "Production-ready Docker image",
      "activity_description": "Create Dockerfile and build a 'production-ready' baseline image based on Ubuntu with Full XD Jar and Java 7.x (U8).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A9",
      "activity_name": "Documentation and final integration verification",
      "activity_description": "Update user documentation for new properties/commands, perform final build, and smoke-test security features and Docker images together.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 104
  }
}

